package com.terrahaul.worldgen.placement;

import com.mojang.serialization.MapCodec;
import com.terrahaul.registry.TerrahaulPlacements;
import com.terrahaul.worldgen.TerrahaulGeneration;
import net.minecraft.core.BlockPos;
import net.minecraft.util.RandomSource;
import net.minecraft.world.level.levelgen.placement.PlacementContext;
import net.minecraft.world.level.levelgen.placement.PlacementFilter;
import net.minecraft.world.level.levelgen.placement.PlacementModifierType;

/**
 * Placement filter {@code terrahaul:terrahaul_only}: passes only in chunks generated by a Terrahaul
 * generator and inside the build height. Used for the deep and high resource layers, which only
 * make sense in Terrahaul's taller world.
 */
public final class TerrahaulOnlyFilter extends PlacementFilter {
    public static final TerrahaulOnlyFilter INSTANCE = new TerrahaulOnlyFilter();
    public static final MapCodec<TerrahaulOnlyFilter> CODEC = MapCodec.unit(() -> INSTANCE);

    private TerrahaulOnlyFilter() {
    }

    @Override
    protected boolean shouldPlace(PlacementContext context, RandomSource random, BlockPos pos) {
        return TerrahaulGeneration.isTerrahaul(context.generator()) && !context.getLevel().isOutsideBuildHeight(pos);
    }

    @Override
    public PlacementModifierType<?> type() {
        return TerrahaulPlacements.TERRAHAUL_ONLY.get();
    }
}
